<?php
/** TEMP PS S1684 mt — petshop-lifecycle-vartai.php v1.0.0 → v1.0.1 (mažos pakuotės be tikslaus įrašo — ne brendo fallback) + grąžinti tų įrašų intervalus į variklio įvertį. */
add_action('init', function(){
  if (!isset($_GET['ps_s1684mt'])) return; global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'S1684 mt'); $f=WPMU_PLUGIN_DIR.'/petshop-lifecycle-vartai.php';
  if(md5_file($f)!=='b8a772b71172754b47d1cfd5492bbc02'){ $o['STOP']='md5'; echo json_encode($o); exit; }
  $n=base64_decode(''); if(md5($n)!=='4f09e6d55f16b5429acd2b8be5c5e443'){ $o['STOP']='payload'; echo json_encode($o); exit; }
  try { token_get_all($n, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']=$e->getMessage(); echo json_encode($o); exit; }
  $old=file_get_contents($f); file_put_contents($f,$n); if(function_exists('opcache_invalidate')) opcache_invalidate($f,true); $o['md5']=md5_file($f);
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code; if($code>=500||$code===0){ file_put_contents($f,$old); $o['ROLLBACK']=1; echo json_encode($o); exit; }
  $t=$p.'ps_refill_tracking'; $rows=$wpdb->get_results("SELECT rt.id, rt.product_id, rt.last_purchase_date, rt.last_order_id FROM $t rt WHERE rt.purchase_count=1",ARRAY_A); $o['grazinta']=array();
  foreach($rows as $r){ $e=$wpdb->get_row($wpdb->prepare("SELECT brendas_slug, svoris_g, kiekis FROM {$p}ps_fakt_eilutes WHERE uzsakymas_id=%d AND preke_id=%d LIMIT 1",$r['last_order_id'],$r['product_id']),ARRAY_A); if(!$e) continue; $g=(int)$e['svoris_g']*max(1,(int)$e['kiekis']); $b=strtolower($e['brendas_slug']); if($g<=0||$g>=1500) continue; if(isset(Petshop_Lifecycle_Vartai::CIKLAI[$b.'|iki1.5kg'])) continue;
    $iv=$g<500?14:30; $wpdb->update($t,array('avg_interval_days'=>$iv,'predicted_empty_date'=>date('Y-m-d',strtotime($r['last_purchase_date'])+$iv*86400)),array('id'=>$r['id'])); $o['grazinta'][]=$b.' '.$g.'g→'.$iv; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
